import {WARNING,FIELDS,evaluate,parseManifest} from './engine.mjs';
const $=id=>document.getElementById(id),items=[];let selected=null,worker=null,workerPromise=null,busy=false,stop=false,manifest=new Map();
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sampleExpected={brand:'Old Tom Distillery',type:'Kentucky Straight Bourbon Whiskey',abv:'45',volume:'750 mL',producer:'Bottled by Old Tom Distillery, Louisville, KY',origin:'',imported:false};
function message(s,error=false){$('message').textContent=s;$('message').className=error?'error':'';}
function current(){return items.find(x=>x.id===selected);}
function inputs(){return Object.fromEntries([...Object.keys(FIELDS).map(k=>[k,$('f-'+k).value]),['imported',$('imported').checked]]);}
function save(){const x=current();if(x)x.expected=inputs();}
function renderQueue(){ $('count').textContent=items.length;$('queue').innerHTML=items.map(x=>`<button class="queue-item ${x.id===selected?'active':''}" data-id="${x.id}" aria-pressed="${x.id===selected}"><strong>${escape(x.name)}</strong><small>${escape(x.processing?'Reading label…':x.error?'Could not read':x.result?x.result.status:'Ready for review')}</small></button>`).join('');$('runall').disabled=busy||!items.length;$('export').disabled=!items.some(x=>x.result);$('demo').disabled=busy; }
function show(id){if(selected)save();selected=id;const x=current();$('empty').hidden=true;$('detail').hidden=false;$('filename').textContent=x.name;$('preview').src=x.url;$('original').href=x.url;for(const k of Object.keys(FIELDS))$('f-'+k).value=x.expected[k]||'';$('imported').checked=!!x.expected.imported;renderResults();renderQueue();}
function renderResults(){const x=current();if(!x)return;$('review').disabled=busy;$('recompare').disabled=busy;$('results').hidden=!x.result;$('status').textContent=x.processing?'Reading…':x.error?'Read failed':x.result?x.result.status:'Ready';$('status').className='badge '+(x.result?'review':'');if(!x.result)return;$('summary').textContent=x.result.matches+' text checks matched';$('timing').textContent=(x.ms/1000).toFixed(2)+'s · '+Math.round(x.confidence)+'% OCR confidence'+(x.edited?' · Text corrected':'');$('rows').innerHTML=x.result.rows.map(r=>`<div class="result-row"><strong>${escape(FIELDS[r.field]||({warning:'Health warning',format:'Warning formatting'}[r.field]))}</strong><div><p>${escape(r.observed)}</p>${r.expected?`<p class="expected">Application / reference: ${escape(r.expected)}</p>`:''}<small>${escape(r.note)}</small></div><span class="badge ${r.status}">${{match:'Match',review:'Review',mismatch:'Mismatch',skip:'N/A'}[r.status]}</span></div>`).join('');$('ocrtext').value=x.text;}
for(const [k,label] of Object.entries(FIELDS)){$('fields').insertAdjacentHTML('beforeend',`<label>${label}<input id="f-${k}" ${k==='abv'?'type="number" min="0" max="100" step="any"':'type="text"'} autocomplete="off" placeholder="${{brand:'Brand on application',type:'e.g. Kentucky Straight Bourbon Whiskey',abv:'45',volume:'750 mL',producer:'Name and address',origin:'For imported beverages'}[k]}"></label>`);}
$('queue').onclick=e=>{const b=e.target.closest('[data-id]');if(b)show(b.dataset.id);};
$('form').oninput=()=>{const x=current();if(!x)return;save();if(x.result){x.result=evaluate(x.text,x.expected,x.confidence);renderResults();renderQueue();}};
async function addFiles(files){if(items.length+files.length>300){message('The queue holds up to 300 images. Start a new session for more.',true);return;}const errors=[];for(const f of files){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>12*1024*1024){errors.push(f.name+': use PNG, JPG or WebP up to 12 MB.');continue;}if(items.some(x=>x.name===f.name)){errors.push(f.name+': duplicate filename; rename it before adding.');continue;}const url=URL.createObjectURL(f);try{const im=new Image();im.src=url;await im.decode();if(im.width*im.height>24000000)throw Error('Image exceeds 24 megapixels.');items.push({id:crypto.randomUUID(),name:f.name,file:f,url,expected:{...(manifest.get(f.name)||{})},text:'',confidence:0});}catch(e){URL.revokeObjectURL(url);errors.push(f.name+': '+e.message);}}if(!selected&&items.length)show(items[0].id);else renderQueue();message(errors.length?errors.join(' '):'Labels added. Enter application details or import a matching JSON file.',!!errors.length);}
$('files').onchange=async e=>{await addFiles([...e.target.files]);e.target.value='';};
$('manifest').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('Application JSON must be under 2 MB.');const a=parseManifest(await f.text());save();manifest=new Map(a.map(x=>[x.filename,x]));for(const x of items){if(manifest.has(x.name)){x.expected={...manifest.get(x.name)};if(x.result)x.result=evaluate(x.text,x.expected,x.confidence);}}if(selected){const id=selected;selected=null;show(id);}message(a.length+' applications imported; '+items.filter(x=>manifest.has(x.name)).length+' filenames paired.');}catch(err){message(err.message,true);}e.target.value='';};
function download(name,data,type='application/json'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('template').onclick=()=>download('applications.json',JSON.stringify([{filename:'old-tom-match.png',...sampleExpected},{filename:'old-tom-mismatch.png',...sampleExpected}],null,2));
async function getWorker(){if(worker)return worker;if(workerPromise)return workerPromise;workerPromise=(async()=>{if(!window.Tesseract)throw Error('Text recognition could not load. Reload the page and try again.');const w=await Tesseract.createWorker('eng',1,{workerPath:new URL('./vendor/worker.min.js',location.href).href,corePath:new URL('./vendor/',location.href).href,langPath:new URL('./vendor/',location.href).href,workerBlobURL:false,logger:m=>{if(busy&&m.status)message(m.status==='recognizing text'?'Reading label · '+Math.round((m.progress||0)*100)+'%':'Preparing local text recognition…');}});await w.setParameters({tessedit_pageseg_mode:'11'});worker=w;return w;})();try{return await workerPromise;}finally{workerPromise=null;}}
async function prepare(file){const im=await createImageBitmap(file);const scale=Math.min(1,2400/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);im.close();return c;}
async function read(x){x.processing=true;x.error=null;renderQueue();renderResults();const start=performance.now();let timer;try{const task=async()=>{const w=await getWorker();const canvas=await prepare(x.file);return w.recognize(canvas);};const output=await Promise.race([task(),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Reading took longer than 45 seconds. Try a smaller, clearer image.')),45000);})]);x.text=output.data.text;x.confidence=output.data.confidence;x.edited=false;x.ms=performance.now()-start;x.result=evaluate(x.text,x.expected,x.confidence);if(!x.text.trim())throw Error('No readable text found. Use a clear image with larger text.');message('Finished '+x.name+' in '+(x.ms/1000).toFixed(2)+' seconds.'+(x.ms>5000?' This exceeded the 5-second target.':''));}catch(e){x.error=e.message;x.result=null;message(x.name+': '+e.message,true);if(worker){await worker.terminate();worker=null;}}finally{clearTimeout(timer);x.processing=false;renderQueue();renderResults();}}
async function run(all=false){if(busy)return;save();busy=true;stop=false;$('stop').hidden=!all;const list=all?[...items]:[current()];try{for(let i=0;i<list.length&&!stop;i++){$('batchprogress').textContent=all?`${i+1} / ${list.length}`:'';await read(list[i]);}}finally{busy=false;$('stop').hidden=true;renderQueue();renderResults();}}
$('form').onsubmit=e=>{e.preventDefault();run();};$('runall').onclick=()=>run(true);$('stop').onclick=()=>{stop=true;message('The queue will stop after the current label.');};
$('recompare').onclick=()=>{const x=current();save();x.text=$('ocrtext').value;x.edited=true;x.result=evaluate(x.text,x.expected,x.confidence);renderResults();renderQueue();message('Comparison updated using corrected text; original OCR confidence retained.');};
$('export').onclick=()=>download('label-lens-results.json',JSON.stringify({generatedAt:new Date().toISOString(),scope:'Decision support; not approval. Warning formatting requires human review.',applications:items.map(({name,expected,text,confidence,edited,ms,result,error})=>({filename:name,expected,text,confidence,edited:!!edited,elapsedMs:ms,result,error}))},null,2));
function wrap(ctx,text,x,y,max,line){let words=text.split(' '),row='';for(const word of words){if(ctx.measureText(row+word).width>max){ctx.fillText(row.trim(),x,y);row='';y+=line;}row+=word+' ';}ctx.fillText(row.trim(),x,y);return y+line;}
async function sampleFile(mismatch){const c=document.createElement('canvas');c.width=1200;c.height=1500;const ctx=c.getContext('2d');ctx.fillStyle='#fffdf6';ctx.fillRect(0,0,1200,1500);ctx.strokeStyle='#173d35';ctx.lineWidth=6;ctx.strokeRect(38,38,1124,1424);ctx.fillStyle='#173d35';ctx.textAlign='center';ctx.font='bold 33px Georgia';ctx.fillText('EST. 1892  /  SMALL BATCH',600,145);ctx.font='bold 78px Georgia';ctx.fillText('OLD TOM',600,305);ctx.font='bold 58px Georgia';ctx.fillText('DISTILLERY',600,385);ctx.font='34px Georgia';ctx.fillText('Kentucky Straight Bourbon Whiskey',600,505);ctx.font='italic 30px Georgia';ctx.fillText('Patiently aged. Carefully crafted.',600,610);ctx.font='bold 42px Arial';ctx.fillText(mismatch?'40% Alc./Vol. (80 Proof)':'45% Alc./Vol. (90 Proof)',600,760);ctx.font='36px Arial';ctx.fillText('750 mL',600,825);ctx.font='28px Arial';ctx.fillText('Bottled by Old Tom Distillery, Louisville, KY',600,940);ctx.textAlign='left';ctx.font='bold 29px Arial';ctx.fillText(mismatch?'Government Warning:':'GOVERNMENT WARNING:',95,1090);ctx.font='28px Arial';wrap(ctx,WARNING.slice('GOVERNMENT WARNING: '.length),95,1140,1010,40);ctx.font='18px Arial';ctx.fillStyle='#67756e';ctx.fillText('FICTIONAL TEST LABEL · NOT FOR SALE',95,1390);return new File([await new Promise(r=>c.toBlob(r))],mismatch?'old-tom-mismatch.png':'old-tom-match.png',{type:'image/png'});}
$('demo').onclick=async()=>{if(items.some(x=>x.name==='old-tom-match.png')){show(items.find(x=>x.name==='old-tom-match.png').id);return;}const files=await Promise.all([sampleFile(false),sampleFile(true)]);for(const f of files)manifest.set(f.name,{...sampleExpected});await addFiles(files);show(items.find(x=>x.name===files[0].name).id);message('Two fictional test labels loaded. Review the queue to test a match and an ABV / warning-heading discrepancy.');};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_label_review_results',title:'Read label comparison results',description:'Read completed comparisons in the current browser queue. Does not run OCR or approve applications.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return items.map(x=>({filename:x.name,result:x.result||null,error:x.error||null}));}})).catch(()=>{});}catch{}}
window.addEventListener('beforeunload',()=>{worker?.terminate();items.forEach(x=>URL.revokeObjectURL(x.url));});
